import { db } from "@/db"; import { vendors } from "@/db/schema"; import { eq } from "drizzle-orm"; import { getCurrentUser, unauthorized, ok } from "@/lib/auth";
export async function PUT(req:Request,{params}:{params:Promise<{id:string}>}){ const u=await getCurrentUser(); if(!u) return unauthorized(); const {id}=await params; const b=await req.json(); const [r]=await db.update(vendors).set({name:b.name,email:b.email||null,phone:b.phone||null,category:b.category||null,status:b.status,city:b.city||null,country:b.country||null,notes:b.notes||null,updatedAt:new Date()}).where(eq(vendors.id,id)).returning(); return ok(r); }
export async function DELETE(_:Request,{params}:{params:Promise<{id:string}>}){ const u=await getCurrentUser(); if(!u) return unauthorized(); const {id}=await params; await db.delete(vendors).where(eq(vendors.id,id)); return ok({deleted:true}); }
